    { topic: 'Verbal Reasoning', subTopic: 'Verbal', text: 'Complete the analogy: Doctor : Hospital :: Teacher : ___', options: ['School', 'Hospital', 'Court', 'Bank'], correct: 0, rationale: 'A doctor works in a hospital; a teacher works in a school.', level: 'understanding' },
    { topic: 'Verbal Reasoning', subTopic: 'Verbal', text: 'Which word does not belong to the group?', options: ['Rose', 'Lotus', 'Mango', 'Lily'], correct: 0, rationale: 'Mango is a fruit; the others are flowers.', level: 'understanding' },

    // ---- Numerical Reasoning (5) ----
    { topic: 'Numerical Reasoning', subTopic: 'Numerical', text: 'What is 15% of 200?', options: ['30', '25', '35', '20'], correct: 0, rationale: '0.15 × 200 = 30.', level: 'application' },
    { topic: 'Numerical Reasoning', subTopic: 'Numerical', text: 'What is the next number in the series: 3, 6, 9, 12, ___?', options: ['15', '14', '13', '18'], correct: 0, rationale: 'The series increases by 3 each time.', level: 'recall' },
    { topic: 'Numerical Reasoning', subTopic: 'Numerical', text: 'What is the average of 10, 20 and 30?', options: ['20', '15', '25', '30'], correct: 0, rationale: 'Sum = 60, divided by 3 = 20.', level: 'application' },
    { topic: 'Numerical Reasoning', subTopic: 'Numerical', text: 'If a shirt costs Rs. 500 and is discounted 20%, what is the sale price?', options: ['Rs. 400', 'Rs. 300', 'Rs. 450', 'Rs. 350'], correct: 0, rationale: '20% of 500 = 100; 500 - 100 = 400.', level: 'application' },
    { topic: 'Numerical Reasoning', subTopic: 'Numerical', text: 'The length and breadth of a rectangle are increased by 15% and 25% respectively. What is the percentage increase in area?', options: ['44%', '40%', '30%', '20%'], correct: 0, rationale: 'New area = 1.15 × 1.25 = 1.4375, so 43.75% ≈ 44%.', level: 'application' },
    { topic: 'Numerical Reasoning', subTopic: 'Numerical', text: 'What is 20% of 150?', options: ['30', '25', '35', '20'], correct: 0, rationale: '0.20 × 150 = 30.', level: 'application' },

    // ---- Logical Sequencing (5) ----
    { topic: 'Logical Sequencing', subTopic: 'Logical', text: 'If A > B and B > C, then which is true?', options: ['A > C', 'C > A', 'A = C', 'B > A'], correct: 0, rationale: 'By transitivity, A > C.', level: 'understanding' },
    { topic: 'Logical Sequencing', subTopic: 'Logical', text: 'All roses are flowers. Some flowers are red. Therefore:', options: ['Some roses may be red', 'All roses are red', 'No rose is red', 'Roses are not flowers'], correct: 0, rationale: 'From the premises, some roses may be red is a valid possibility.', level: 'understanding' },
    { topic: 'Logical Sequencing', subTopic: 'Logical', text: 'Which shape completes the pattern: circle, square, triangle, circle, square, ___?', options: ['Triangle', 'Circle', 'Square', 'Rectangle'], correct: 0, rationale: 'The pattern repeats every three shapes.', level: 'application' },
    { topic: 'Logical Sequencing', subTopic: 'Logical', text: 'Look at this series: 53, 53, 40, 40, 27, 27, ___? Which number comes next?', options: ['14', '12', '27', '53'], correct: 0, rationale: 'The series subtracts 13 after each pair: 53, 53, 40, 40, 27, 27, 14.', level: 'application' },
    { topic: 'Logical Sequencing', subTopic: 'Logical', text: 'All A are B. All B are C. Therefore:', options: ['All A are C', 'Some A are C', 'No A are C', 'Some C are not A'], correct: 0, rationale: 'By transitivity, if A ⊂ B and B ⊂ C, then A ⊂ C.', level: 'understanding' },
    { topic: 'Logical Sequencing', subTopic: 'Logical', text: 'No A are B. Some B are C. Therefore:', options: ['Some C may be A', 'All C are A', 'No C are A', 'Some C are not B'], correct: 0, rationale: 'No definite conclusion about A and C can be drawn; some C may be A is possible.', level: 'understanding' },

    // ---- Spatial / Abstract Reasoning (5) ----
    { topic: 'Spatial Reasoning', subTopic: 'Spatial', text: 'How many faces does a cube have?', options: ['6', '4', '8', '12'], correct: 0, rationale: 'A cube has 6 faces.', level: 'recall' },
    { topic: 'Spatial Reasoning', subTopic: 'Spatial', text: 'How many edges does a tetrahedron have?', options: ['6', '4', '8', '12'], correct: 0, rationale: 'A tetrahedron has 6 edges.', level: 'recall' },
    { topic: 'Spatial Reasoning', subTopic: 'Spatial', text: 'If a square is rotated 45°, its outline most resembles a:', options: ['Diamond', 'Circle', 'Triangle', 'Rectangle'], correct: 0, rationale: 'A rotated square becomes diamond-shaped.', level: 'application' },
    { topic: 'Spatial Reasoning', subTopic: 'Spatial', text: 'How many vertices does a cube have?', options: ['8', '6', '12', '4'], correct: 0, rationale: 'A cube has 8 vertices (corners).', level: 'recall' },
    { topic: 'Spatial Reasoning', subTopic: 'Spatial', text: 'How many faces does a tetrahedron have?', options: ['4', '6', '8', '12'], correct: 0, rationale: 'A tetrahedron has 4 triangular faces.', level: 'recall' },
    { topic: 'Spatial Reasoning', subTopic: 'Spatial', text: 'Which 3D shape can be made from a net of 6 equal squares?', options: ['Cube', 'Cylinder', 'Cone', 'Sphere'], correct: 0, rationale: 'Six equal squares form a cube.', level: 'application' }
